-- Arias Suite — migración 062
-- Importación inicial del registro PENDIENTES desde PENDIENTES (1).xlsm.
--
-- Se conserva el contenido operativo del archivo:
-- ubicación, categoría, pendiente, estado original, asignado, prioridad,
-- observación y fecha. La fecha se normaliza desde la celda de fecha detectada
-- en el origen.
--
-- Normalización operativa:
--   Terminado -> COMPLETED
--   resto -> PENDING
--   Alta -> HIGH
--   Media/vacío -> NORMAL
--
-- No modifica migraciones anteriores.

BEGIN;

CREATE TABLE IF NOT EXISTS public.maintenance_pending_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  hotel_id uuid NOT NULL REFERENCES public.hotels(id) ON DELETE CASCADE,
  location text,
  category text,
  pending text NOT NULL,
  status text NOT NULL DEFAULT 'PENDING'
    CHECK (status IN ('PENDING', 'COMPLETED')),
  source_status text,
  assigned_to text,
  priority text NOT NULL DEFAULT 'NORMAL'
    CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'CRITICAL')),
  source_priority text,
  observation text,
  source_date date,
  source_file text NOT NULL,
  source_row integer NOT NULL,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ux_maintenance_pending_source UNIQUE (hotel_id, source_file, source_row)
);

CREATE INDEX IF NOT EXISTS ix_maintenance_pending_hotel_status
  ON public.maintenance_pending_items (hotel_id, status);
CREATE INDEX IF NOT EXISTS ix_maintenance_pending_hotel_priority
  ON public.maintenance_pending_items (hotel_id, priority);
CREATE INDEX IF NOT EXISTS ix_maintenance_pending_hotel_date
  ON public.maintenance_pending_items (hotel_id, source_date);

ALTER TABLE public.maintenance_pending_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS maintenance_pending_select ON public.maintenance_pending_items;
CREATE POLICY maintenance_pending_select
  ON public.maintenance_pending_items FOR SELECT TO authenticated
  USING (public.has_hotel_access(hotel_id));

DROP POLICY IF EXISTS maintenance_pending_insert ON public.maintenance_pending_items;
CREATE POLICY maintenance_pending_insert
  ON public.maintenance_pending_items FOR INSERT TO authenticated
  WITH CHECK (public.has_hotel_permission(hotel_id, 'maintenance.create'));

DROP POLICY IF EXISTS maintenance_pending_update ON public.maintenance_pending_items;
CREATE POLICY maintenance_pending_update
  ON public.maintenance_pending_items FOR UPDATE TO authenticated
  USING (public.has_hotel_permission(hotel_id, 'maintenance.update'))
  WITH CHECK (public.has_hotel_permission(hotel_id, 'maintenance.update'));

DROP POLICY IF EXISTS maintenance_pending_delete ON public.maintenance_pending_items;
CREATE POLICY maintenance_pending_delete
  ON public.maintenance_pending_items FOR DELETE TO authenticated
  USING (public.has_hotel_permission(hotel_id, 'maintenance.update'));

DO $$
DECLARE
  v_hotel_id uuid;
BEGIN
  SELECT h.id INTO v_hotel_id
  FROM public.hotels h
  JOIN public.tenants t ON t.id = h.tenant_id
  WHERE h.code = 'SB-DZ' AND t.code = 'SBH'
  LIMIT 1;

  IF v_hotel_id IS NULL THEN
    RAISE EXCEPTION 'No se encontró el hotel SB-DZ para importar PENDIENTES.';
  END IF;

  INSERT INTO public.maintenance_pending_items (
    hotel_id, location, category, pending, status, source_status, assigned_to,
    priority, source_priority, observation, source_date, source_file, source_row
  )
  SELECT
    v_hotel_id,
    NULLIF(x.location, ''),
    NULLIF(x.category, ''),
    x.pending,
    x.status_normalized,
    NULLIF(x.source_status, ''),
    NULLIF(x.assigned_to, ''),
    x.priority_normalized,
    NULLIF(x.source_priority, ''),
    NULLIF(x.observation, ''),
    x.source_date::date,
    'PENDIENTES (1).xlsm',
    x.source_row
  FROM jsonb_to_recordset($json$
