    row_data ->> 3,
    row_data ->> 4,
    NULLIF(row_data ->> 5, ''),
    NULLIF(row_data ->> 6, ''),
    row_data ->> 7,
    NULLIF(row_data ->> 8, ''),
    NULLIF(row_data ->> 9, ''),
    NULLIF(row_data ->> 10, '')::date,
    'PENDIENTES (1).xlsm',
    (row_data ->> 0)::integer
  FROM jsonb_array_elements($json$
